import java.util.List;
import java.util.stream.Collectors;

record Product(String name, double price) {}

class MethodReferenceDemo {
    public static void main(String[] args) {
        var products = List.of(
            new Product("Laptop", 899.99),
            new Product("Mouse", 25.50),
            new Product("Keyboard", 75.00)
        );

        // Lambda version - more verbose
        products.forEach(p -> System.out.println(p));

        // Method reference - cleaner
        products.forEach(System.out::println);

        // Extracting names with lambda
        var names = products.stream()
            .map(p -> p.name())
            .collect(Collectors.toList());

        // Same with method reference - intent is crystal clear
        var namesClean = products.stream()
            .map(Product::name)  // unbound instance method reference
            .collect(Collectors.toList());
    }
}

import java.util.List;
import java.util.function.BiFunction;
import java.util.function.Function;
import java.util.function.Supplier;

record Order(Long id, String customer, double amount) {}

class MethodReferenceTypes {
    public static void main(String[] args) {
        // 1. Static method reference
        BiFunction<Integer, Integer, Integer> maxFunc = Math::max;
        System.out.println(maxFunc.apply(10, 20));  // 20

        // 2. Bound instance method reference - specific object
        var orderTemplate = new Order(0L, "ACME Corp", 0.0);
        Supplier<String> customerGetter = orderTemplate::customer;  // bound to orderTemplate
        System.out.println(customerGetter.get());  // ACME Corp

        // 3. Unbound instance method reference - object comes as parameter
        Function<String, String> upperCaser = String::toUpperCase;  // no specific String yet
        System.out.println(upperCaser.apply("hello"));  // HELLO

        var orders = List.of("small", "medium", "large");
        orders.stream()
            .map(String::toUpperCase)  // each stream element becomes the receiver
            .forEach(System.out::println);

        // 4. Constructor reference
        Function<String, Order> orderFactory = Order::new;  // needs matching constructor
    }
}

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

record Employee(String name, String department, LocalDate hireDate, double salary) {}

class ComparatorSortingDemo {
    public static void main(String[] args) {
        var employees = new ArrayList<>(List.of(
            new Employee("Alice", "Engineering", LocalDate.of(2020, 3, 15), 85000),
            new Employee("Bob", "Sales", LocalDate.of(2019, 7, 22), 65000),
            new Employee("Charlie", "Engineering", LocalDate.of(2021, 1, 10), 80000),
            new Employee("Diana", "Sales", LocalDate.of(2018, 11, 5), 70000)
        ));

        // Simple sort by name
        employees.sort(Comparator.comparing(Employee::name));

        // Sort by salary descending
        employees.sort(Comparator.comparing(Employee::salary).reversed());

        // Multi-field: department ascending, then hire date descending within each dept
        employees.sort(
            Comparator.comparing(Employee::department)
                      .thenComparing(Employee::hireDate, Comparator.reverseOrder())
        );

        employees.forEach(System.out::println);
    }
}

import java.util.List;
import java.util.function.Function;
import java.util.function.Supplier;
import java.util.stream.Collectors;

record User(String username, String email) {
    // Constructor for username only, email defaults
    public User(String username) {
        this(username, username + "@example.com");
    }
}

class ConstructorReferenceDemo {
    public static void main(String[] args) {
        // Supplier for no-arg constructor (needs a no-arg constructor in User)
        Supplier<List<String>> listFactory = ArrayList::new;
        var newList = listFactory.get();

        // Function for single-arg constructor
        Function<String, User> userFactory = User::new;  // uses User(String) constructor
        User alice = userFactory.apply("alice");
        System.out.println(alice);  // User[username=alice, email=alice@example.com]

        // Stream mapping with constructor reference
        var usernames = List.of("bob", "charlie", "diana");
        var users = usernames.stream()
            .map(User::new)  // creates User for each username
            .collect(Collectors.toList());

        users.forEach(System.out::println);
    }
}
